html:
{%- set company = frappe.get_doc("Company", doc.company) -%}
{%- set customer = frappe.get_doc("Customer", doc.customer) -%}

{% set chunk_size = 8 %}
{% set total_items = doc.items|length %}
{% set chunks = (total_items // chunk_size) + (1 if total_items % chunk_size else 0) %}
<style>
 @page {
  margin: 5mm;   /* shrink print page margins */
}
body, .print-format {
  margin: 0;
  padding: 0;
  font-family: Arial, sans-serif;
  font-size: 9pt;
}
.wrapper {
  width: 100%;
  padding: 4px;
  border: 1px solid #000;
  box-sizing: border-box;
}

/* Header */
.header { 
    display:flex; 
    flex-direction:column; 
    border-bottom:1px solid #000; 
    padding:6px; 
    position: relative; /* MODIFIED: Added for positioning context */
}
.company-block { width:65%; }
.company-name { font-weight:bold; font-size:11pt; }
.company-details { font-size:10pt; line-height:1.2; }
.gst-block { width:35%; text-align:right; font-size:10pt; }

/* MODIFIED: Style for the new Page Number element */
.page-info {
    position: absolute;
    top: 8px;
    right: 8px;
    font-size: 9pt;
    font-weight: bold;
    color: #444;
}


/* Customer/Quotation Info */
.info { border-bottom:1px solid #000; display:flex; font-size:10pt; }
.info-left, .info-right { width:50%; padding:6px; }
.info-left { border-right:1px solid #000; }
.info-label { font-weight:bold; width:110px; display:inline-block; }

/* Items Table */
table.items { 
    width:100%; 
    border-collapse:collapse; 
    font-size:10pt;
    table-layout: fixed; /* Ensures column widths are respected */
}
.items th {
  border:1px solid #000; padding:4px; background:#f5f5f5;
  text-align:center; font-weight:bold; font-size:10pt;
}

/* Set specific widths for each column */
.items th:nth-child(1), .items td:nth-child(1) { width: 5%; }
.items th:nth-child(2), .items td:nth-child(2) { width: 25%; }
.items th:nth-child(3), .items td:nth-child(3) { width: 35%; }
.items th:nth-child(4), .items td:nth-child(4) { width: 7%; }
.items th:nth-child(5), .items td:nth-child(5) { width: 8%; }
.items th:nth-child(6), .items td:nth-child(6) { width: 8%; }
.items th:nth-child(7), .items td:nth-child(7) { width: 12%; }


.items td {
  padding:4px;
  border:1px solid #000;
  border-bottom:1px dotted #000;
  word-wrap: break-word; /* Ensures long text wraps */
}

.items td:last-child { border-right:1px solid #000; }
.items tr:last-child td { border-bottom:1px solid #000; }
.text-center { text-align:center; }
.text-right { text-align:right; }

/* CSS for empty rows to remove horizontal lines */
.empty-row td {
    height: 18px;
    border-top: none;
    border-bottom: none;
}

/* Totals Section */
.summary { display:flex; border-bottom:1px solid #000; font-size:10pt; }
.summary-left { width:60%; padding:6px; border-left:1px solid #000; }
.summary-right { width:40%; padding:6px; border-right:1px solid #000; border-left:1px solid #000; }
.label { text-align:right; font-weight:bold; }
.value { text-align:right; }

/* Amount in words */
.in-words { border-bottom:1px solid #000; padding:6px; font-size:10pt; font-weight:bold; }

/* Tax & Bank */
.tax-bank { display:flex; border-bottom:1px solid #000; font-size:10pt; }
.tax-details, .bank-details { width:50%; padding:6px; }
.tax-details { border-right:1px solid #000; }

/* Footer */
.footer { display:flex; font-size:10pt; padding:6px; }
.footer-left { width:70%; }
.footer-right { width:30%; text-align:center; }
.sign-space { height:50px; }

/* Page breaks */
.page-break { page-break-before: always; }
</style>

{% for page in range(chunks) %}
<div class="wrapper">

  <!-- Header -->
  <div class="header" style="display:flex; flex-direction:column; border-bottom:1px solid #000; padding:6px;">

    <!-- Top Row: Logo + Company Info -->
    <div style="display:flex; justify-content:space-between; align-items:center; width:100%; margin-bottom:8px;">

        <!-- Logo -->
        <div class="logo" style="width:127px; height:115px;">
            <img src="/files/Dacs inc Logo.jpeg" alt="Company Logo" style="max-width:100%; max-height:100%; object-fit:contain;">
        </div>

        <!-- Company Info -->
        <div class="company-block" style="flex-grow:1; padding-left:10px;">
            <div class="company-name" style="font-weight:bold; font-size:12pt;">{{ company.name }}</div>
            <div class="company-details" style="font-size:10pt; line-height:1.3;">
                Jaya Sai Towers No.40, 1st & 2nd floor, Sajjan Rao Road, Parvathipuram,<br>
                V.V.Puram, BANGALORE - 560004, Karnataka, India<br>
                GSTIN/UIN: 29AAIFD5710C1ZQ<br>
                Phone: 080-41234140, 080-41206892 | Email: marketing@dacsinc.in<br>
                Web: www.dacsinc.in
            </div>
        </div>
    </div>

    <!-- Bottom Row: Quotation Info -->
    <div style="text-align:center; border-top:1px solid #000; padding-top:6px; font-size:12pt;">
        <div style="font-weight:bold; font-size:14pt; margin-bottom:4px;">SALES ORDER</div>
        <div>No: {{ doc.name }} | Date: {{ frappe.utils.formatdate(doc.transaction_date, "dd-MMM-yyyy") }}</div>
    </div>
</div>

  <!-- Customer / Quotation Info -->
  <div class="info">
    <div class="info-left">
      <div><strong>M/s. {{ doc.customer_name }}</strong></div>
      <div>{{ doc.address_display or "No address" }}</div>
      <div><span class="info-label">GST No</span>: {{ customer.gstin or "N/A" }}</div>
      <div><span class="info-label">Phone</span>: {{ doc.contact_mobile or "N/A" }}</div>
    </div>
    <div class="info-right">

      <div><span class="info-label">Contact Person</span>: {{ doc.contact_person or "-" }}</div>
    </div>
  </div>

  <!-- Items -->
  <table class="items">
    <thead>
      <tr>
        <th>Sl No</th>
        <th>Product Code & Product Name</th>
        <th>Description</th>
        <th>Qty</th>
        <th>Rate</th>
        <th>Tax%</th>
        <th>Amount</th>
      </tr>
    </thead>
    <tbody>
      {# Logic to ensure a fixed number of rows #}
      {% set start = page * chunk_size %}
      {% set end = (page + 1) * chunk_size %}
      {% set items_on_page = doc.items[start:end] %}

      {# Loop 1: Render the actual item rows for the current page #}
      {% for item in items_on_page %}
      <tr>
        <td class="text-center">{{ loop.index + start }}</td>
        <td>{{ item.item_code}} - {{item.item_name}}</td>
        <td>{{ item.description or "" }}</td>
        <td class="text-center">{{ item.qty }}</td>
        <td class="text-right">{{ "%.2f"|format(item.rate or 0) }}</td>
        <td class="text-center">{{ item.item_tax_template or "0" }}%</td>
        <td class="text-right">{{ "%.2f"|format(item.amount or 0) }}</td>
      </tr>
      {% endfor %}

      {# Loop 2: Render empty rows to fill the remaining space up to chunk_size #}
      {% if (items_on_page|length) < chunk_size %}
        {% for i in range((items_on_page|length), chunk_size) %}
        <tr class="empty-row">
          <td>&nbsp;</td>
          <td>&nbsp;</td>
          <td>&nbsp;</td>
          <td>&nbsp;</td>
          <td>&nbsp;</td>
          <td>&nbsp;</td>
          <td>&nbsp;</td>
        </tr>
        {% endfor %}
      {% endif %}
    </tbody>
  </table>

  {# Show totals/summary only on last page #}
  {% if page + 1 == chunks %}
    <!-- Totals -->
    <div class="summary">
      <div class="summary-left">
        <strong>Total Items:</strong> {{ doc.items|length }}<br>
        <strong>Qty:</strong> {{ doc.total_qty or 0 }}
      </div>
      <div class="summary-right">
        <table class="totals">
          <tr><td>Sub Total</td><td class="value">{{  "%.2f"|format(doc.net_total) }}</td></tr>
          {% for tax in doc.taxes %}
          <tr><td>{{ tax.account_head }}</td><td class="value">{{  "%.2f"|format(tax.tax_amount) }}</td></tr>
          {% endfor %}
          {% if doc.rounding_adjustment %}
          <tr><td>Round Off</td><td class="value">{{  "%.2f"|format(doc.rounding_adjustment) }}</td></tr>
          {% endif %}
          <tr><td>Grand Total</td><td class="value">{{  "%.2f"|format(doc.rounded_total or doc.grand_total) }}</td></tr>
        </table>
      </div>
    </div>

    <!-- Amount in words -->
    <div class="in-words">
      Amount in Words: Rupees {{ frappe.utils.money_in_words(doc.rounded_total or doc.grand_total) }}
    </div>

    <!-- Tax & Bank -->
    <div class="tax-bank">
      <div class="tax-details">
        <strong>Tax Summary:</strong><br>
        {% for tax in doc.taxes %}
          {{ tax.account_head }} : {{  "%.2f"|format(tax.tax_amount) }}<br>
        {% endfor %}
      </div>
      <div class="bank-details">
        <strong>Bank Details:</strong><br>
        Bank: Yes Bank<br>
        A/c No: 092484600001445<br>
        IFSC: YESB0000924<br>
        Branch: Gandhi Bazaar
      </div>
    </div>

    <!-- Footer -->
    <div class="footer" style="display:flex; justify-content:space-between; font-size:10pt; border-top:1px solid #000; padding-top:10px; align-items:stretch;">

    <!-- Terms & Conditions -->
    <div class="footer-left" style="width:70%; padding-right:10px; line-height:1.4; border-right:1px solid #000; display:flex; flex-direction:column; justify-content:space-between;">
        <strong>Terms and Conditions:</strong>
        <div style="margin-top:4px;">
            {{ doc.terms or "-" }}
        </div>
    </div>

    <!-- Company & Signature -->
    <div class="footer-right" style="width:28%; text-align:center; padding-left:10px; display:flex; flex-direction:column; justify-content:flex-end;">
        For <strong>{{ doc.company }}</strong><br><br><br><br>
        <div style="border-bottom:1px solid #000; width:80%; margin:0 auto;"></div>
        Authorised Signatory
    </div>

</div>
  {% endif %}

</div>

{% if not loop.last %}
<div class="page-break"></div>
{% endif %}
{% endfor %}
